# scope:founder is the character instigating the conversion
on_faith_conversion = {
	events = {
		faith_conversion.0001	# Convert capital county
		faith_conversion.0003	# Convert close family
		faith_conversion.1002	# Player-only narrative-notification event
		faith_conversion.1101   # Notify vassals of conversion
	}

	effect = {
		set_variable = {
			name = old_rite
			value = scope:old_rite
			days = 30
		}
		pam_on_conversion_effect = yes
		pam_remove_forbidden_personal_tenet_secret_if_invalid_effect = yes
		update_syncretism_personal_tenet_effect = yes
		# EP3 - State Faith
		if = {
			limit = {
				OR = {
					government_allows = state_faith
					top_liege = { government_allows = state_faith }
				}
			}
			# Character uses decision to Adopt State Faith
			if = {
				limit = { has_character_flag = adopted_state_faith }
				top_liege = {
					if = {
						limit = {
							has_opinion_modifier = {
								target = root
								modifier = converted_to_state_faith_opinion
							}
						}
						remove_opinion = {
							target = root
							modifier = converted_to_state_faith_opinion
						}
					}
					every_vassal = {
						custom = every_governor_of_state_faith
						limit = {
							has_opinion_modifier = {
								target = root
								modifier = converted_to_state_faith_opinion
							}
						}
						remove_opinion = {
							target = root
							modifier = converted_to_state_faith_opinion
						}
					}
				}
			}

			# Character is converted to state rite and gains influence
			if = {
				limit = {
					rite = top_liege.primary_title.state_rite
					government_has_flag = government_has_influence
				}
				change_influence = minor_influence_gain
				hidden_effect = {
					top_liege.primary_title.state_rite = { save_scope_as = new_rite }
					create_character_memory = { type = adopted_state_faith_memory }
					scope:new_memory = {
						if = {
							limit = { exists = scope:old_rite }
							set_variable = {
								name = old_rite
								value = scope:old_rite
							}
							# Savegame and non-English loc compatibility; do not rename or remove
							set_variable = {
								name = old_faith
								value = scope:old_rite.faith
							}
						}
						else = {
							set_variable = {
								name = old_rite
								value = root.rite
							}
							set_variable = {
								name = old_faith
								value = root.faith
							}
						}
						set_variable = {
							name = new_rite
							value = scope:new_rite
						}
						set_variable = {
							name = new_faith
							value = scope:new_rite.faith
						}
						set_variable = {
							name = title
							value = root.top_liege.primary_title
						}
					}
				}
			}
		}
		# PAM Acts of Apostles tenet Effects
		if = {
			limit = {
				exists = scope:founder
				scope:founder.rite = { rite_has_parameter = tenet_acts_of_apostles_legitimacy_from_converts }
			}
			scope:founder = {
				send_interface_message = {
					type = event_religious_good
					title = tenet_acts_of_apostles_toast_conversion_title
					left_icon = root
					if = {
						limit = { exists = root.primary_title }
						add_legitimacy = {
							value = minor_legitimacy_gain
							multiply = root.primary_title.tier
						}
					}
					else = {
						add_legitimacy = minor_legitimacy_gain
					}
					if = {
						limit = { is_playable_character = yes }
						change_spiritual_fulfillment = medium_spiritual_fulfillment_value
					}
				}
			}
		}
		# Antipope removal
		pam_remove_sponsored_antipope_effect = {
			SPONSOR = root
			FAITH = scope:old_faith
		}
	}
}

# Code on-action: character changes faith or rite. Not called when a character gets a faith on birth, creation, and similar
# Root is the character
# scope:old_faith is the faith they used to have
# scope:old_rite is the rite they used to have (can be equal to current rite)
on_rite_change = {
	effect = {
		pam_on_conversion_effect = yes
		christian_clergy_learn_liturgical_language_effect = yes
		pam_remove_forbidden_personal_tenet_secret_if_invalid_effect = yes
		check_for_equal_doctrine_effect = yes
		every_held_title = {
			update_dynamic_coa = yes
		}

		add_character_flag = changed_rite_flag

		# Conversion memories
		create_conversion_memory_effect = yes

# Achievements
if = {
	limit = { is_ai = no }

	if = { # FP2 - Basque In My Glory
		limit = { faith = faith:basque_pagan }
		add_achievement_global_variable_effect = {
			VARIABLE = fp2_basque_in_my_glory_achievement_unlocked
			VALUE = yes
		}
	}
}

# Hostage story cycle
if = {
