		is_adult = no
		# Did they just change to their captor's culture
		faith = warden.faith
	}
	save_scope_as = hostage
	warden = {
		trigger_event = bp2_yearly.8050
	}
}

if = {
	limit = {
		has_variable = japan_1010_discount
		var:japan_1010_discount = faith
	}
	remove_variable = japan_1010_discount
}

if = {
	limit = {
		has_character_flag = tgp_japan_1040_discount
		faith.religion = religion:shintoism_religion
	}
	remove_character_flag = tgp_japan_1040_discount
}

#Lose Mandala if you change to a monotheist faith
mandala_no_longer_polytheist_effect = yes

	# PAM - Catalysts
	if = {
		limit = {
			has_pam_dlc_trigger = yes
			exists = situation:the_christian_church
		}
		if = {
			limit = {
				highest_held_title_tier >= tier_county
				scope:old_faith ?= {
					religion = religion:christianity_religion
				}
				religion != religion:christianity_religion
				situation:the_christian_church ?= {
					situation_top_has_catalyst = catalyst_the_christian_church_ruler_converted_from_christianity
				}
			}
			situation:the_christian_church = {
				trigger_situation_catalyst = catalyst_the_christian_church_ruler_converted_from_christianity
			}
		}
		if = {
			limit = {
				highest_held_title_tier >= tier_county
				scope:old_faith ?= {
					religion != religion:christianity_religion
				}
				religion = religion:christianity_religion
				situation:the_christian_church ?= {
					situation_top_has_catalyst = catalyst_the_christian_church_ruler_converted_to_christianity
				}
			}
			situation:the_christian_church = {
				trigger_situation_catalyst = catalyst_the_christian_church_ruler_converted_to_christianity
			}
		}
		# Great Schism: kings+ and landed prelates crossing between the schism-pair rites face a confrontation
		pam_schism_rite_conversion_dissent_effect = yes
		pam_offer_great_schism_stance_effect = yes
	}
	# Tenet popularity
	pam_tenet_popularity_on_rite_change_effect = yes

	if = {
		limit = {
			exists = clerical_elector_title
			rite = { NOT = { rite_has_parameter = has_clerical_electors } }
		}
		pam_destroy_cardinal_title_effect = { CARDINALATE = clerical_elector_title }
	}

}
events = {
	faith_conversion.0001 # convert capital
	faith_conversion.0003 # Convert close family
	faith_conversion.0002 # Remove obsolete modifiers
	faith_conversion.0004 # Convert Theocracies
	faith_conversion.0005 # Update marriage opinions

pam_on_conversion_effect = {
	if = {
		limit = { is_ai = no }
		add_character_flag = {
			flag = faith_conversion_recently_converted
			years = pam_ui_conversion_cooldown
		}
	}
}

pam_tenet_popularity_on_rite_change_effect = {
	if = {
		limit = { is_landed = yes }
		faith = { save_scope_as = tp_new_faith }
		rite = { save_scope_as = tp_new_rite }
		if = {
			limit = {
				exists = scope:old_rite
				scope:old_rite != scope:tp_new_rite
			}
			scope:old_rite.faith = { save_scope_as = tp_old_faith }
			if = {
				limit = { scope:tp_old_faith = { has_tenet_popularity_trigger = yes } }
				scope:old_rite = {
					every_rite_tenet = {
						status = core
						save_scope_as = tp_tenet
						scope:tp_old_faith = {
							change_tenet_popularity = {
								target = scope:tp_tenet
								change = miniscule_tenet_popularity_loss
							}
						}
					}
				}
			}
		}
		if = {
			limit = { scope:tp_new_faith = { has_tenet_popularity_trigger = yes } }
			scope:tp_new_rite = {
				every_rite_tenet = {
					status = core
					save_scope_as = tp_tenet
					scope:tp_new_faith = {
						change_tenet_popularity = {
							target = scope:tp_tenet
							change = miniscule_tenet_popularity_gain
						}
					}
				}
			}
		}
	}
}

pam_tax_nonbelievers_faith_conversion_on_action = {
	trigger = {
		exists = scope:actor
		root != scope:actor
		scope:actor = {
			has_personal_tenet_flag = tax_nonbelievers_fulfillment_from_conversion
		}
	}
	effect = {
		scope:actor = {
			pam_tax_nonbelievers_conversion_fulfillment_effect = yes
		}
	}
}

create_conversion_memory_effect = {
	if = {
		limit = {
			exists = scope:old_rite
			scope:old_rite != rite # A rite that diverged into its own faith keeps its object; nobody converted
			NOT = { has_character_flag = conversion_memory_recently_created }
		}
		save_temporary_scope_as = conversion_memory_owner
		add_character_flag = { # The conversion window fires on_rite_change twice for a same-faith switch
			flag = conversion_memory_recently_created
			days = 2
		}
		if = {
			limit = {
				exists = scope:old_faith
				scope:old_faith != faith
			}
			create_character_memory = { type = converted_faith_memory }
			scope:new_memory = {
				set_variable = {
					name = old_faith
					value = scope:old_faith
				}
				set_variable = {
					name = new_faith
					value = scope:conversion_memory_owner.faith
				}
				set_variable = {
					name = new_rite
					value = scope:conversion_memory_owner.rite
				}
			}
		}
		else = {
			create_character_memory = { type = converted_rite_memory }
			scope:new_memory = {
				set_variable = {
					name = old_rite
					value = scope:old_rite
				}
				set_variable = {
					name = new_rite
					value = scope:conversion_memory_owner.rite
				}
			}
		}
		if = {
			limit = { is_adult = no }
			scope:new_memory = { set_variable = childhood_memory }
		}
	}
}

# Fired when you convert to a new faith. Convert capital county.
faith_conversion.0001 = {
	hidden = yes

	trigger = {
		is_landed = yes
		primary_title.tier > tier_barony
		exists = capital_county
		exists = scope:old_faith
		capital_county.faith = scope:old_faith
	}

	immediate = {
		capital_county ?= {
			save_scope_as = converted_ruler_capital
		}

		# set_county_rite also sets the parent faith, so a faith change would convert the capital for free
		if = {
			limit = { capital_county.faith = root.faith }

			# if their capital and ours coincide region holder's rite wins - try to convert adjacent county root owns
			if = {
				limit = {
					capital_county.clerical_region_title ?= {
						holder ?= {
							capital_county = scope:converted_ruler_capital
							faith = root.faith
							rite != root.rite
							NOR = {
								root.puppet:theological_agent_puppet ?= this
								root.puppet:external_theological_agent_puppet ?= this
							}
						}
					}
				}

				capital_county = {
					random_neighboring_county = {
						limit = {
							holder = root
							faith = root.faith
							clerical_region_title ?= {
								OR = {
									not = { exists = holder }
									holder.rite = root.rite
									holder.capital_county != prev
								}
							}
						}

						set_county_rite = root.rite
					}
				}
			}
			else = {
				capital_county = { set_county_rite = root.rite }
			}
		}

		root.rite = {
			force_refresh_head_of_rite = yes
		}
	}
}

scripted_trigger faith_conversion_0003_valid_character = {
	faith = scope:old_faith
	# If conversion is within the same religion, check the rite is the same
	trigger_if = {
		limit = { scope:new_faith.religion = scope:old_faith.religion }
		rite = scope:old_rite
	}
	is_alive = yes
	is_ai = yes
	# A relative's conversion must not drag along characters the rest of the conversion systems protect
	NOR = {
		has_character_flag = ai_will_not_convert
		this = faith.religious_head
		rite.head_of_rite ?= this
	}
}

# Fired when you convert to a new faith. Convert close family.
faith_conversion.0003 = {
	hidden = yes

	immediate = {
		faith = { save_scope_as = new_faith }
		rite = { save_scope_as = new_rite }
		every_spouse = {
			limit = {
				faith_conversion_0003_valid_character = yes
				is_landed = no
			}
			set_character_rite = root.rite
		}
		every_close_family_member = {
			limit = {
				faith_conversion_0003_valid_character = yes
				OR = {
					# A minor fostered outside the realm keeps their guardian's rite
					AND = {
						is_child_of = root
						OR = {
							is_adult = no
							is_landed = no
						}
						trigger_if = {
							limit = {
								is_adult = no
								any_relation = {
									type = guardian
								}
							}
							any_relation = {
								type = guardian
								count = all
								target_is_liege_or_above = root
							}
						}
					}
					# Cascade travels down the hierarchy, not up to a parent or sibling
					target_is_liege_or_above = root
				}
			}
			set_character_rite = root.rite
		}
	}
}

faith_conversion.0004 = {
	hidden = yes

	trigger = {
		government_has_flag = government_is_theocracy
		is_landed = yes
		rite = {
			rite_has_doctrine = doctrine_theocracy_lay_clergy
		}
	}

	immediate = {
		assign_feudal_governments_effect = yes
	}
}

# For softening opinion penalties, e.g., I believed in monogamous faith but was in a polygamous marriage, but now I've been converted to polygamous faith.
faith_conversion.0005 = {
	hidden = yes

	trigger = {
		any_consort = { }
	}

	immediate = {
		every_consort = {
			save_scope_as = this_consort
			root = {
				update_active_consort_opinion_effect = { PARTNER = scope:this_consort }
			}
		}
	}
}

	option = { 
		name = faith_conversion.1001.a
	}

	option = { 
		name = faith_conversion.1001.b
		# Gain scope:template priest as a courtier & earmark them for future friendship.
		add_courtier = scope:template_priest
		reverse_add_opinion = {
			target = scope:template_priest
			modifier = pious_opinion
			opinion = 50
		}
		set_relation_potential_friend = scope:template_priest
	}

	after = {
		hidden_effect = {
			if = {
				limit = {
					this != scope:template_priest.host
				}
				scope:template_priest = {		
					death = {
						death_reason = death_disappearance
					}
				}
			}
		}
		if = {
			limit = {
				scope:template_priest ?= {
					has_character_flag = is_naked
				}
			}
			scope:template_priest = {
				remove_character_flag = is_naked
			}
		}


		add_character_flag  = {
			flag = recent_convert
			years = 20
		}
	}
}

faith_conversion.1002 = {
	hidden = yes

	immediate = {
		# If it's desirable to delay this event (e.g., due to decision) a little, do so.
		if = {
			limit = { has_character_flag = delay_player_faith_conversion_notification_event }
			trigger_event = {
				id = faith_conversion.1001
				days = 7
			}
		}
		# Otherwise, just send it.
		else = { trigger_event = faith_conversion.1001 }
	}
}

faith_conversion.1101 = {
	hidden = yes

	immediate = {
		every_vassal = {
			limit = {
				is_ai = no
			}
			send_interface_toast = {
				title = faith_conversion.1101.toast
				left_icon = root

				show_as_tooltip = {
					root = {
						set_character_faith = faith
					}
				}
			}
		}
	}
}

}

